const themes=['Bewustwording & Organisatie','Integriteit & Veilige Werkomgeving','Veilige Publieke Taak','Informatiepositie & Informatiebeveiliging','Beleid & Handhaving','Communicatie'];
const normSlugs=['1-bewustwording-en-organisatie','2-integriteit-veilige-werkomgeving','3-veilige-publieke-taak','4-informatiepositie-informatiebeveiliging','5-beleid-en-handhaving','6-communicatie'];
const productSlugs=['bewustwording-organisatie','integriteit-veilige-werkomgeving','veilige-publieke-taak','informatiepositie-informatiebeveiliging','beleid-handhaving','communicatie'];
const captions=['Herkennen begint met bewustzijn.','Een sterke organisatie begint van binnen.','Veilig werken. Samen beschermen.','Informatie verbinden. Weerbaarheid versterken.','Van beleid naar een krachtige aanpak.','De juiste boodschap brengt mensen in beweging.'];
const icons=['M5 18v-3a4 4 0 018 0v3M9 8a3 3 0 100-6 3 3 0 000 6M17 8a3 3 0 100-6M17 11a4 4 0 014 4v3','M12 2l8 3v6c0 5-8 10-8 10S4 16 4 11V5zM8 11l3 3 5-6','M4 20v-8l8-8 8 8v8M9 20v-6h6v6','M4 10V5h16v5M4 14v5h16v-5M9 12h6M12 9v6','M4 20h16M7 16V8M12 16V8M17 16V8M3 5l9-3 9 3z','M4 6h16v10H9l-5 4zM8 10h8'];
const icon=i=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.25" aria-hidden="true"><path d="${icons[i]}"/></svg>`;
let pages=[];const $=s=>document.querySelector(s);const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const href=s=>'/'+s+(s?'/':'');
function header(){return `<a class="skip" href="#main">Naar inhoud</a><div class="topline"><span>RIEC Limburg</span><span>Samen slimmer tegen ondermijnende criminaliteit</span></div><header><a class="wordmark" href="/" aria-label="Limburgse Norm — Home"><img class="site-logo" src="/assets/limburgse-norm-logo.png" width="321" height="208" alt="Limburgse Norm"></a><nav aria-label="Hoofdnavigatie"><a href="/" data-nav="">Home</a>${['Handreiking','Productenoverzicht'].map((t,j)=>`${j?'<a class="check-nav" href="/checklist/">Checklist</a>':''}<div class="nav-group"><a href="/${j?'productenoverzicht':'handreiking'}/">${t}</a><button class="drop-toggle" aria-label="${t} submenu" aria-expanded="false"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg></button><div class="dropdown"><span class="eyebrow">${j?'Hulpmiddelen per thema':'De zes thema’s'}</span>${themes.map((n,i)=>`<a href="${href((j?productSlugs:normSlugs)[i])}"><span>0${i+1}</span>${n}<b>↗</b></a>`).join('')}</div></div>`).join('')}<a href="/contact/">Contact</a></nav><div class="header-actions"><button class="search-btn" aria-label="Website doorzoeken"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/></svg></button><button class="mobile-toggle" aria-label="Menu openen" aria-expanded="false"><span></span><span></span></button></div></header><div class="reading-progress"></div>`}
function footer(){return `<section class="contact-band"><div><span class="eyebrow">Samen zetten we de volgende stap</span><h2>Weerbaarheid<br>begint bij verbinding<span>.</span></h2></div><a href="/contact/" class="circle-link" aria-label="Neem contact op">↗</a></section><footer><div class="footer-top"><a href="/" class="footer-brand" aria-label="Limburgse Norm — Home"><img class="footer-site-logo" src="/assets/limburgse-norm-logo.png" width="321" height="208" alt="Limburgse Norm" loading="lazy"></a><p>Eén gezamenlijke norm.<br>Voor een weerbaar Limburg.</p><a class="riec-logo" href="https://www.rieclimburg.nl/" target="_blank" rel="noopener"><img src="/assets/RIEC_Limburg_Wit_RGB-qdghe6ijji1r0owggrrp14smv1vnbd95tgb4yw75kw.png" alt="RIEC Limburg"></a></div><div class="footer-bottom"><span>Onderdeel van RIEC Limburg</span><div><a href="/cc-by-nc-nd-4-0-akte/">Copyright</a><a href="/proclaimer/">Proclaimer</a><a href="/privacy-policy/">Privacy Policy</a><a href="/klachten/">Klachten</a><a href="/contact/">Contact</a></div><a href="#top">Naar boven ↑</a></div></footer>`}
function themeRows(product=false){return themes.map((n,i)=>`<a class="theme-row" href="${href((product?productSlugs:normSlugs)[i])}"><span class="row-num">0${i+1}</span><span class="row-icon">${icon(i)}</span><span class="row-text"><h3>${n}</h3><span>${product?'Bekijk producten en hulpmiddelen':captions[i]}</span></span><span class="row-arrow">↗</span></a>`).join('')}
function home(p){let d=document.createElement('div');d.innerHTML=p.html;let paras=[...d.querySelectorAll('p')].filter(x=>x.textContent.trim());return `<section class="home-hero"><div class="hero-copy"><div class="eyebrow"><span class="pulse"></span> De Limburgse Norm</div><h1>Samen voor<br>een weerbaar<br><span>Limburg.</span></h1><p>Eén gezamenlijke norm. Een sterke overheid.<br>Samen bieden we tegenwicht aan ondermijning.</p><a class="button white" href="/handreiking/">Ontdek de handreiking <span>↗</span></a><div class="hero-bottom"><span>GEMEENTEN · PROVINCIE · WATERSCHAP</span><a href="#themas" aria-label="Ontdek de zes thema’s"><span aria-hidden="true">↓</span></a></div></div><div class="hero-visual"><img src="/assets/port.jpg" alt="Luchtfoto van logistieke infrastructuur met water, schepen en containers"><div class="vizier a"></div><div class="vizier b"></div><div class="image-label"><span>VERBINDEN. VERSTERKEN.</span><span>Voor een weerbare overheid<br>en samenleving.</span></div></div></section><section class="intro section-wrap"><div><span class="eyebrow purple">01 — Welkom</span><h2>De dijken overal<br>even hoog.</h2></div><div class="intro-text">${paras.slice(0,2).map(p=>p.outerHTML).join('')}<a class="text-link" href="/handreiking/">Meer over de Limburgse Norm <span>↗</span></a></div></section><section id="themas" class="themes section-wrap"><div class="section-heading"><div><span class="eyebrow purple">02 — De zes thema’s</span><h2>Weerbaarheid is<br>een gezamenlijke opgave.</h2></div><p>Zes thema’s. Onlosmakelijk verbonden.<br>Ontdek wat jouw organisatie kan doen.</p></div><div class="theme-list">${themeRows()}</div><div class="theme-outro">${paras.slice(3).map(p=>p.outerHTML).join('')}</div></section><section class="next-step"><div class="next-image"><img src="/assets/logistics.jpg" alt="Logistiek terrein vanuit de lucht" loading="lazy"><div class="vizier a"></div></div><div class="next-copy"><span class="eyebrow">03 — Van inzicht naar actie</span><h2>Weet waar je staat.<br>Bepaal je volgende stap.</h2><p>Breng de weerbaarheid van jouw organisatie in kaart. Gebruik de checklist als vertrekpunt voor een gerichte aanpak.</p><a class="button white" href="/checklist/">Naar de checklist <span>↗</span></a><a class="text-link light" href="/productenoverzicht/">Bekijk de producten en hulpmiddelen ↗</a></div></section>`}
function page(p){let ni=normSlugs.indexOf(p.slug),pi=productSlugs.indexOf(p.slug),isnorm=ni>=0,isprod=pi>=0;let group=isnorm?'Handreiking':isprod?'Productenoverzicht':'Limburgse Norm';let groupHref=isnorm?'/handreiking/':isprod?'/productenoverzicht/':'/';let content=document.createElement('div');content.innerHTML=p.html;
 // repair malformed relative norm links in source
 content.querySelectorAll('a').forEach(a=>{let h=a.getAttribute('href');if(/^\d-\d$/.test(h))a.setAttribute('href','#'+h);});
 // create deterministic heading anchors and accurate table of contents
 let headings=[...content.querySelectorAll('h2,h3')].filter(h=>h.textContent.trim());headings.forEach((h,i)=>{h.id=h.id||'section-'+i});
 // remove redundant original norm table of contents, replace with complete sidebar
 if(isnorm){let first=headings[0];if(first){let keep=false;for(let c of [...content.childNodes]){if(c===first)keep=true;if(!keep)c.remove();}}}
 let toc=headings.map(h=>`<a href="#${h.id}">${esc(h.textContent.trim())}</a>`).join('');
 if(p.slug==='productenoverzicht')content.innerHTML=`<p>Een dynamisch aanbod van producten en diensten om de weerbaarheid van jouw organisatie te versterken. Neem voor gebruik en ondersteuning contact op met de accountmanagers van het RIEC.</p><div class="theme-list compact">${themeRows(true)}</div>`;
 if(p.slug==='contact'){content.innerHTML=`<div class="contact-details"><h2 id="section-0">Contactgegevens RIEC Limburg</h2><a href="tel:+31433897540"><small>Bel ons</small><span>+31 (0)43 – 389 75 40 ↗</span></a><a href="mailto:weerbaresamenleving@rieclimburg.nl"><small>Mail ons · weerbare samenleving</small><span>weerbaresamenleving@rieclimburg.nl ↗</span></a><div><small>Correspondentieadres</small><span>Postbus 1992<br>6201 BZ Maastricht</span></div></div>`;}
 if(p.slug==='checklist'){content.innerHTML='<h2 id="section-0">Digitale checklist</h2><p>Versie: 04-03-2024</p><div class="download-notice"><strong>De download is momenteel niet beschikbaar.</strong><p>De oorspronkelijke downloadserver geeft een foutmelding. Vraag de digitale checklist aan bij RIEC Limburg.</p><a class="button purple-button" href="mailto:weerbaresamenleving@rieclimburg.nl?subject=Aanvraag%20digitale%20checklist%20Limburgse%20Norm">Vraag de checklist aan ↗</a></div>';toc='<a href="#section-0">Digitale checklist</a>'; }
 let title=isnorm?themes[ni]:p.title;let lead=isnorm?captions[ni]:isprod?'Praktische producten, kennis en hulpmiddelen voor jouw organisatie.':p.slug==='handreiking'?'Van gezamenlijke ambitie naar een weerbare organisatie.':p.slug==='checklist'?'Breng in kaart waar jouw organisatie staat.':p.slug==='productenoverzicht'?'Kennis en hulpmiddelen om samen verder te komen.':p.slug==='contact'?'Samen maken we Limburg weerbaarder.':'';
 let side=isnorm?`<span class="eyebrow purple">In dit thema</span>${toc}<a class="sidebar-product" href="${href(productSlugs[ni])}">Bijbehorende producten ↗</a>`:isprod?`<span class="eyebrow purple">Producten per thema</span>${themes.map((n,i)=>`<a ${i===pi?'class="selected"':''} href="${href(productSlugs[i])}">${n}</a>`).join('')}<a class="sidebar-product" href="${href(normSlugs[pi])}">Naar de normen ↗</a>`:`<span class="eyebrow purple">Op deze pagina</span>${toc||'<a href="/handreiking/">Handreiking ↗</a><a href="/productenoverzicht/">Productenoverzicht ↗</a>'}`;
 return `<section class="page-hero section-wrap"><div class="breadcrumbs"><a href="/">Home</a><span>/</span>${group!=='Limburgse Norm'?`<a href="${groupHref}">${group}</a><span>/</span>`:''}<span>${esc(title)}</span></div><div class="page-heading"><div><span class="eyebrow purple">${isnorm?'Thema 0'+(ni+1)+' — Handreiking':isprod?'Thema 0'+(pi+1)+' — Producten':group}</span><h1>${esc(title)}<span class="title-dot">.</span></h1>${lead?`<p>${lead}</p>`:''}</div><div class="page-symbol">${isnorm||isprod?icon(isnorm?ni:pi):'<span class="big-corner"></span>'}</div></div></section><div class="content-layout section-wrap"><aside>${side}</aside><article class="prose">${content.innerHTML}</article></div>${isnorm?`<section class="next-theme section-wrap"><span class="eyebrow purple">${ni<5?'Volgend thema':'Verder aan de slag'}</span><a href="${ni<5?href(normSlugs[ni+1]):'/checklist/'}"><h2>${ni<5?themes[ni+1]:'De checklist'}</h2><span>↗</span></a></section>`:''}`;
}
function wire(){document.querySelectorAll('.drop-toggle').forEach(b=>b.onclick=e=>{let active=b.getAttribute('aria-expanded')==='true';document.querySelectorAll('.drop-toggle').forEach(x=>x.setAttribute('aria-expanded','false'));b.setAttribute('aria-expanded',String(!active));});$('.mobile-toggle').onclick=()=>{let b=$('.mobile-toggle');b.setAttribute('aria-expanded',String(b.getAttribute('aria-expanded')!=='true'));document.body.classList.toggle('menu-open')};$('.search-btn').onclick=()=>{$('#search-dialog').showModal();$('#search-input').focus()};$('#close-search').onclick=()=>$('#search-dialog').close();$('#search-input').oninput=e=>{let q=e.target.value.trim().toLocaleLowerCase('nl');$('#search-results').innerHTML=q?pages.filter(p=>(p.title+' '+p.text).toLocaleLowerCase('nl').includes(q)).map(p=>{let idx=p.text.toLocaleLowerCase('nl').indexOf(q);return `<a href="${href(p.slug)}"><strong>${esc(p.title)}</strong><span>${esc(p.text.slice(Math.max(0,idx-50),Math.max(0,idx-50)+180))}…</span><b>↗</b></a>`}).join('')||'<p>Geen resultaten. Probeer een andere zoekterm.</p>':'<p>Zoek in alle thema’s, normen en producten.</p>'};document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('menu-open');document.querySelectorAll('.drop-toggle').forEach(b=>b.setAttribute('aria-expanded','false'));}});document.addEventListener('click',e=>{if(!e.target.closest('.nav-group'))document.querySelectorAll('.drop-toggle').forEach(b=>b.setAttribute('aria-expanded','false'))});document.querySelectorAll('nav a').forEach(a=>{if(a.pathname===location.pathname)a.setAttribute('aria-current','page')});if('IntersectionObserver'in window){let o=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');o.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.theme-row,.intro,.section-heading,.next-step').forEach(e=>{e.classList.add('reveal');o.observe(e)})}window.addEventListener('scroll',()=>{let max=document.documentElement.scrollHeight-innerHeight;$('.reading-progress').style.width=(max>0?scrollY/max*100:0)+'%'},{passive:true});if(location.hash)setTimeout(()=>{let el=document.getElementById(decodeURIComponent(location.hash.slice(1)));el?.scrollIntoView()},80);}
fetch('/content.json').then(r=>r.json()).then(data=>{pages=data;let slug=decodeURIComponent(location.pathname).replace(/^\/|\/$/g,'');let p=pages.find(p=>p.slug===slug);if(!p){document.title='Pagina niet gevonden — Limburgse Norm';$('#app').innerHTML=header()+'<main id="main" class="section-wrap not-found"><h1>Even de weg kwijt?</h1><p>Deze pagina is niet gevonden.</p><a class="button purple-button" href="/">Naar home ↗</a></main>'+footer();}else{document.title=(p.slug?p.title:'Samen voor een weerbaar Limburg')+' — Limburgse Norm';$('#app').innerHTML=header()+`<main id="main">${slug?page(p):home(p)}</main>`+footer();}wire()}).catch(()=>{$('#app').innerHTML='<main class="section-wrap"><h1>De pagina kon niet laden.</h1><p>Vernieuw de pagina om opnieuw te proberen.</p></main>'});
